156	     7	/** Preço de uma estadia: noites, soma das noites, desconto e total. */
157	     8	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
158	     9	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
159	    10	
160	    11	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
161	    12	        int nights = 0;
162	    13	        BigDecimal subtotal = Money.ZERO;
163	    14	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
164	    15	            subtotal = subtotal.add(nightPrice(room, night));
165	    16	            nights++;
166	    17	        }
167	    18	        BigDecimal discount = plan.discountOn(subtotal);
168	    19	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
169	    20	    }
170	    21	
171	    22	    static BigDecimal nightPrice(Room room, LocalDate night) {
172	    23	        BigDecimal rate = room.nightlyRate();
173	    24	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
174	    25	    }
175	    26	
176	    27	    static boolean isHighSeason(LocalDate night) {
177	    28	        Month month = night.getMonth();
178	    29	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
179	    30	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
180	    31	    }
181	    32	}
