    23	    static NewReservation parse(String body) {
    24	        JsonNode json = readObject(body);
    25	        LocalDate checkIn = date(json, "checkIn");
    26	        LocalDate checkOut = date(json, "checkOut");
    27	        if (!checkOut.isAfter(checkIn)) {
    28	            throw AppException.invalid("A saída precisa ser depois da entrada");
    29	        }
    30	        JsonNode guests = json.get("guests");
    31	        if (guests == null || !guests.isInt() || guests.intValue() < 1) {
    32	            throw AppException.invalid("guests precisa ser um número inteiro maior que zero");
    33	        }
    34	        return new NewReservation(roomNumber(json), text(json, "guestName"), text(json, "guestEmail"),
    35	                identity(json), checkIn, checkOut, guests.intValue(), ratePlan(json));
    36	    }
