    38	    private static JsonNode readObject(String body) {
    39	        try {
    40	            JsonNode json = MAPPER.readTree(body);
    41	            if (json == null || !json.isObject()) {
    42	                throw AppException.invalid("O corpo precisa ser um objeto JSON");
    43	            }
    44	            return json;
    45	        } catch (JsonProcessingException e) {
    46	            throw AppException.invalid("O corpo não é um JSON válido");
    47	        }
    48	    }
    49	
    50	    private static int roomNumber(JsonNode json) {
    51	        JsonNode node = json.get("roomNumber");
    52	        if (node == null || !node.isInt()) {
    53	            throw AppException.invalid("roomNumber precisa ser um número inteiro");
    54	        }
    55	        return node.intValue();
    56	    }
    57	
    58	    private static RatePlan ratePlan(JsonNode json) {
    59	        try {
    60	            return RatePlan.valueOf(text(json, "ratePlan"));
    61	        } catch (IllegalArgumentException e) {
    62	            throw AppException.invalid("ratePlan desconhecido");
    63	        }
    64	    }
    65	
    66	    private static LocalDate date(JsonNode json, String field) {
    67	        try {
    68	            return LocalDate.parse(text(json, field));
    69	        } catch (DateTimeParseException e) {
    70	            throw AppException.invalid(field + " precisa estar no formato AAAA-MM-DD");
    71	        }
    72	    }
    73	
    74	    private static GuestIdentity identity(JsonNode json) {
    75	        Map<String, String> given = new LinkedHashMap<>();
    76	        for (String field : IdentityKinds.allFieldNames()) {
    77	            if (json.hasNonNull(field)) {
    78	                given.put(field, text(json, field));
    79	            }
    80	        }
    81	        IdentityKind kind = IdentityKinds.resolve(given.keySet()).orElseThrow(() -> AppException.invalid(
    82	                "Informe a identificação de um único jeito: " + IdentityKinds.allFieldNames()));
    83	        return new GuestIdentity(kind, given);
    84	    }
