    86	    private static String text(JsonNode json, String field) {
    87	        JsonNode node = json.get(field);
    88	        if (node == null || !node.isTextual() || node.textValue().isBlank()) {
    89	            throw AppException.invalid(field + " é obrigatório e precisa ser um texto");
    90	        }
    91	        return node.textValue();
    92	    }
