    42	        app.get("/reservations/{id}", ctx -> json(ctx, 200, Views.reservation(reservations.get(id(ctx)))));
    43	        app.post("/reservations/{id}/confirmation", reservation(reservations::confirm));
    44	        app.post("/reservations/{id}/cancellation", reservation(reservations::cancel));
    45	        app.post("/reservations/{id}/check-in", reservation(reservations::checkIn));
